import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';

/// Cultiva's retro sound effects (generated by tools/audio/make_sfx.py).
enum SfxName { plant, ripen, harvest, coin, done, buy }

/// Plays one sound effect. Swappable so tests never touch the platform.
abstract class SfxPlayer {
  Future<void> play(SfxName name);
}

/// Default player: silent (tests, and before [Sfx.player] is set in main).
class SilentSfxPlayer implements SfxPlayer {
  const SilentSfxPlayer();
  @override
  Future<void> play(SfxName name) async {}
}

/// Records what would have played (for tests).
class FakeSfxPlayer implements SfxPlayer {
  final played = <SfxName>[];
  @override
  Future<void> play(SfxName name) async => played.add(name);
}

/// Real player: one low-latency player per sound, mixed with other audio.
class AudioSfxPlayer implements SfxPlayer {
  AudioSfxPlayer({this.volume = 0.6});

  final double volume;
  final _players = <SfxName, AudioPlayer>{};
  bool _configured = false;

  Future<void> _configure() async {
    _configured = true;
    // Never pause the player's music or podcast for a blip.
    await AudioPlayer.global.setAudioContext(
      AudioContextConfig(focus: AudioContextConfigFocus.mixWithOthers).build(),
    );
  }

  @override
  Future<void> play(SfxName name) async {
    if (!_configured) await _configure();
    var p = _players[name];
    if (p == null) {
      p = _players[name] = AudioPlayer(playerId: 'sfx_${name.name}')
        // Blips never need playback position. The default updater asks for a
        // new frame every vsync while "playing", and low-latency mode never
        // reports completion, so it would keep the app from ever idling.
        ..positionUpdater = null;
      await p.setPlayerMode(PlayerMode.lowLatency);
      await p.setReleaseMode(ReleaseMode.stop);
    }
    await p.stop();
    await p.play(AssetSource('sfx/${name.name}.wav'), volume: volume);
  }
}

/// App-wide entry point. Respects the Sound setting; never throws.
abstract final class Sfx {
  static bool enabled = true;
  static SfxPlayer player = const SilentSfxPlayer();

  static void play(SfxName name) {
    if (!enabled) return;
    player.play(name).catchError((Object e) {
      if (kDebugMode) debugPrint('Sfx ${name.name} failed: $e');
    });
  }
}
